def check_min_heap(arr):
    n = len(arr)
    for i in range(n//2 - 1, -1, -1):
        j = 2*i + 1
        if j < n and arr[i] > arr[j]:
            return False
        if j + 1 < n and arr[i] > arr[j+1]:
            return False
    return True

